```javascript
import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial, Color, Vector3 } from 'three/webgpu';
import { uniform, mix, smoothstep, uv, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-collection-row';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const inkColor = new THREE.Color(inkHex);
  const paperColor = new THREE.Color(paperHex);
  const accentColor = new THREE.Color(accentHex);
  const surfaceColor = new THREE.Color(surfaceHex);

  // ── State uniforms ──
  const hoverState = uniform(0);
  const focusState = uniform(0);
  const pressState = uniform(0);

  // ── Row background: machined-brushed-metal plane ──
  const ROW_W = 5.2;
  const ROW_H = 0.72;
  const rowGeo = new THREE.PlaneGeometry(ROW_W, ROW_H, 1, 1);

  const rowMat = new MeshBasicNodeMaterial({ transparent: true });
  rowMat.opacityNode = float(0.92);

  let metalTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.repeat.set(2, 1);
      metalTex = tex;
      rowMat.colorNode = mix(
        vec3(surfaceColor.r * 1.1, surfaceColor.g * 1.1, surfaceColor.b * 1.15),
        mix(
          vec3(metalTex.value),
          vec3(inkColor.r + 0.03, inkColor.g + 0.03, inkColor.b + 0.05),
          float(0.35)
        ),
        hoverState
      );
      rowMat.needsUpdate = true;
    });
  } else {
    rowMat.colorNode = mix(
      vec3(surfaceColor),
      vec3(inkColor),
      hoverState
    );
  }

  // accent edge: left vertical bar glow that intensifies on hover/focus
  const accentEdge = mix(
    float(0.0),
    float(1.0),
    smoothstep(float(0.92), float(1.0), uv().x)
  );
  const edgeMix = mix(
    vec3(0.0, 0.0, 0.0),
    vec3(accentColor),
    accentEdge.mul(hoverState.max(focusState))
  );

  // Combine edge glow over base
  if (config.imageUrl) {
    // will be re-assigned once tex loads; provide fallback now
    rowMat.colorNode = mix(
      vec3(surfaceColor),
      vec3(inkColor),
      hoverState
    ).add(edgeMix.mul(0.6));
  }

  const rowMesh = new THREE.Mesh(rowGeo, rowMat);
  rowMesh.position.set(0, 0, 0);
  group.add(rowMesh);

  // ── Divider line (thin accent-tinted) ──
  const divGeo = new THREE.PlaneGeometry(ROW_W * 0.92, 0.008);
  const divMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  divMat.colorNode = mix(
    mix(vec3(inkColor), vec3(accentColor), float(0.12)),
    vec3(accentColor),
    hoverState.max(focusState).mul(float(0.6))
  );
  divMat.opacityNode = mix(float(0.35), float(0.85), hoverState.max(focusState));
  const divider = new THREE.Mesh(divGeo, divMat);
  divider.position.set(0, -ROW_H * 0.5 - 0.01, 0.001);
  group.add(divider);

  // ── Left accent rail (thin vertical bar) ──
  const railGeo = new THREE.PlaneGeometry(0.025, ROW_H * 0.78);
  const railMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  railMat.colorNode = vec3(accentColor);
  railMat.opacityNode = mix(float(0.35), float(1.0), hoverState.max(focusState));
  const rail = new THREE.Mesh(railGeo, railMat);
  rail.position.set(-ROW_W * 0.46, 0, 0.002);
  group.add(rail);

  // ── Text rendering (from config.textContent) ──
  const textItems =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  const.titleLabelAlign = 'left';
  const metaLabelAlign = 'right';

  let titleObj = null;
  let metaObj = null;
  for (const item of textItems) {
    const role = item.role ?? 'body';
    const txt = item.text ?? '';
    if (!txt) continue;
    const fontSize = item.typography?.fontSize ?? (role === 'title' ? 0.34 : role === 'meta' ? 0.09 : 0.13);
    const isTitle = role === 'title' || role === 'headline';
    const isMeta = role === 'meta' || role === 'caption';
    const align = isMeta ? 'right' : 'left';
    const colorHex = isTitle ? paperHex : isMeta ? '#9aa0aa' : paperHex;

    const textObj = ctx.fontAtlas.createText(txt, {
      fontSize: Math.round(fontSize * 1000),
      color: colorHex,
      align,
      maxWidthPx: isTitle ? 2600 : 1200,
      letterSpacingPx: isMeta ? 80 : 0,
    });

    if (isTitle) {
      titleObj = textObj;
      // scale text object to scene units roughly
      textObj.position.set(-ROW_W * 0.42, 0.0, 0.003);
      group.add(textObj);
    } else if (isMeta) {
      metaObj = textObj;
      textObj.position.set(ROW_W * 0.42, 0.0, 0.003);
      group.add(textObj);
    } else {
      textObj.position.set(-ROW_W * 0.42, -0.04, 0.003);
      group.add(textObj);
    }
    textMeshes.push(textObj);
  }

  // ── Interaction state ──
  let isHovered = false;
  let isFocused = false;
  let isPressed = false;
  const timelines = [];

  // Entrance: rise-in
  const enterTl = gsap.timeline();
  group.position.y += 0.15;
  group.scale.set(0.985, 0.985, 0.985);
  enterTl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  enterTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  enterTl.to(rowMat, { opacity: 0.92, duration: 0.5, ease: 'power2.out' }, 0);
  rowMat.opacityNode = float(0.0);
  // animate opacity via uniform-style: use a JS property proxy since MeshBasicNodeMaterial doesn't have direct uniform for opacity in TSL
  // Re-assign opacityNode after a frame using a uniform
  const opUnif = uniform(0);
  rowMat.opacityNode = opUnif;
  enterTl.to(opUnif, { value: 0.92, duration: 0.5, ease: 'power2.out' }, 0);
  divMat.opacityNode = mix(float(0.35), float(0.85), hoverState.max(focusState));
  railMat.opacityNode = mix(float(0.2), float(1.0), hoverState.max(focusState));
  timelines.push(enterTl);

  // ── Event handlers ──
  group.userData.handlers = {
    onPointerEnter: () => {
      isHovered = true;
      gsap.to(hoverState, { value: 1, duration: 0.4, ease: 'power2.out' });
      gsap.to(rowMesh.position, { z: 0.06, duration: 0.4, ease: 'power2.out' });
      gsap.to(divider.position, { z: 0.07, duration: 0.4, ease: 'power2.out' });
    },
    onPointerLeave: () => {
      isHovered = false;
      if (!isFocused) {
        gsap.to(hoverState, { value: 0, duration: 0.4, ease: 'power2.out' });
        gsap.to(rowMesh.position, { z: 0, duration: 0.4, ease: 'power2.out' });
        gsap.to(divider.position, { z: 0.001, duration: 0.4, ease: 'power2.out' });
      }
    },
    onPointerDown: () => {
      isPressed = true;
      gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
      gsap.to(pressState, { value: 1, duration: 0.12, ease: 'power2.out' });
    },
    onPointerUp: () => {
      if (!isPressed) return;
      isPressed = false;
      gsap.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.15, ease: 'power2.out' });
      gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out', delay: 0.12 });
      gsap.to(pressState, { value: 0, duration: 0.3, ease: 'power2.out' });
      ctx.emit('hub-collection.select', { rowId: group.name });
    },
    onFocus: () => {
      isFocused = true;
      gsap.to(focusState, { value: 1, duration: 0.3, ease: 'power2.out' });
    },
    onBlur: () => {
      isFocused = false;
      if (!isHovered) {
        gsap.to(focusState, { value: 0, duration: 0.3, ease: 'power2.out' });
      }
    },
  };

  // ── Contact shadow (subtle: grounded row) ──
  const shadowGeo = new THREE.PlaneGeometry(ROW_W * 0.9, ROW_H * 1.4);
  const shadowMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = uniform(0.25);
  // radial falloff via uv distance
  const shadowOpacity = uniform(0.25);
  const cu = uv();
  const dist = cu.sub(vec3(0.5, 0.5, 0.0)).length();
  shadowMat.opacityNode = float(0.25).mul(smoothstep(float(0.55), float(0.1), dist));
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -ROW_H * 0.45, -0.02);
  shadow.rotation.x = -0.05;
  group.add(shadow);

  // ── Cleanup ──
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(hoverState);
    gsap.killTweensOf(focusState);
    gsap.killTweensOf(pressState);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(rowMesh.position);
    gsap.killTweensOf(divider.position);

    rowGeo.dispose();
    divGeo.dispose();
    railGeo.dispose();
    shadowGeo.dispose();
    rowMat.dispose();
    divMat.dispose();
    railMat.dispose();
    shadowMat.dispose();

    if (metalTex) metalTex.dispose && metalTex.dispose();

    textMeshes.forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) {
        if (Array.isArray(m.material)) m.material.forEach((mm) => mm.dispose());
        else m.material.dispose();
      }
    });
  };

  return group;
}
